mapper.select:
SELECT NULL AS id, tenant_id, NULL AS user_id, cat_l1, '' AS cat_l2, SUM(weight) AS weight, NULL AS update_time
FROM user_interest_stat
WHERE user_id = #{userId}
AND tenant_id = #{tenantId}
GROUP BY tenant_id, cat_l1
ORDER BY weight DESC
LIMIT #{limit}

SELECT DISTINCT product_id FROM product_view_log
WHERE user_id = #{userId}
  AND view_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)

SELECT b.product_id
FROM product_view_log a
JOIN product_view_log b
  ON b.user_id = a.user_id AND b.product_id != #{productId}
 AND b.view_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
WHERE a.product_id = #{productId}
  AND a.view_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
GROUP BY b.product_id
ORDER BY COUNT(DISTINCT a.user_id) DESC, b.product_id DESC
LIMIT #{limit}
